package native
import("bytes";"testing")
func TestAreaGeometryOwned(t *testing.T){s,err:=New(42);if err!=nil{t.Fatal(err)};defer s.Close();for _,c:=range []string{`{"op":"resize","width":60,"height":24}`,`{"op":"area","id":1,"x":5,"y":4,"width":10,"height":5,"padding":0,"border":"none"}`,`{"op":"area","id":2,"parent":1,"x":8,"y":1,"width":10,"height":5,"padding":1,"border":"double"}`}{if _,err=s.CommandRaw([]byte(c));err!=nil{t.Fatal(err)}};before,_:=s.Snapshot();row,err:=s.AreaGeometry(2);expected:=[12]float64{13,5,10,5,13,5,2,4,15,7,6,1};if err!=nil||row==nil||*row!=expected{t.Fatal(row,err)};row[0]=-99;again,_:=s.AreaGeometry(2);if again[0]!=13{t.Fatal("borrowed")};after,_:=s.Snapshot();if !bytes.Equal(before,after){t.Fatal("mutated")};if _,err=s.AreaGeometry(0);err==nil{t.Fatal("invalid")};missing,err:=s.AreaGeometry(999);if err!=nil||missing!=nil{t.Fatal("absent",err)}}
